fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();

    // If input has length 0 or 1, return it unchanged.
    if n <= 1 {
        return numbers;
    }

    // Result length = 2 * n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for i in 0..n {
        // Insert the original element at even indices
        result.push(numbers[i]);

        // Insert delimiter after every element except the last one
        if i != n - 1 {
            result.push(delimiter);
        }
    }

    result
}